#!/usr/bin/env node
/**
 * SessionStart Hook - Knowledge Staleness Check
 *
 * Fires: Once per session (startup, resume, clear, compact)
 * Purpose: Warn if persona knowledge is stale (>30 days since last sync)
 *
 * Exit Codes:
 *   0 - Always (non-blocking advisory hook)
 */

const fs = require('fs');
const path = require('path');

let isHookEnabled;
try {
  ({ isHookEnabled } = require('./lib/ck-config-utils.cjs'));
} catch {
  isHookEnabled = () => true;
}

if (!isHookEnabled('check-knowledge-staleness')) {
  process.exit(0);
}

function main() {
  try {
    const stateFile = path.join(__dirname, '..', 'knowledge-state.yaml');
    if (!fs.existsSync(stateFile)) {
      process.exit(0);
    }

    const content = fs.readFileSync(stateFile, 'utf-8');
    const lines = content.split('\n');

    let threshold = 30;
    let inPersonas = false;
    let currentPersona = null;
    const personas = {};

    for (const line of lines) {
      const trimmed = line.trim();

      if (trimmed.startsWith('staleness_threshold_days:')) {
        threshold = parseInt(trimmed.split(':')[1].trim(), 10) || 30;
      } else if (trimmed === 'personas:') {
        inPersonas = true;
      } else if (inPersonas && line.startsWith('  ') && !line.startsWith('    ') && trimmed.endsWith(':')) {
        currentPersona = trimmed.slice(0, -1);
        personas[currentPersona] = { last_sync: null };
      } else if (currentPersona && line.startsWith('    ') && trimmed.startsWith('last_sync:')) {
        const val = trimmed.split(':').slice(1).join(':').trim();
        personas[currentPersona].last_sync = val === 'null' ? null : val;
      }
    }

    const now = Date.now();
    const msPerDay = 86400000;
    let staleCount = 0;
    const total = Object.keys(personas).length;

