  let data;
  try {
    data = JSON.parse(hookInput);
  } catch (parseError) {
    // Fail-open for unparseable input
    console.error('WARN: JSON parse failed, allowing operation');
    timer.end({ status: 'warn', exit: 0, note: 'json-parse-failed', error: parseError.message });
    process.exit(0);
  }

