"""
WebResearchBridge — creates real research_fn for MicroQueryRunner.
Uses DuckDuckGo for zero-API-key web search.
Falls back to requests-based scraping if DDG fails.
"""

import json
import time
import warnings
from typing import Optional

warnings.filterwarnings("ignore", message=".*renamed.*ddgs.*")

_LAST_CALL_TIME = 0.0
_MIN_DELAY_S = 1.5


def _rate_limit():
    global _LAST_CALL_TIME
    now = time.time()
    elapsed = now - _LAST_CALL_TIME
    if elapsed < _MIN_DELAY_S:
        time.sleep(_MIN_DELAY_S - elapsed)
    _LAST_CALL_TIME = time.time()


def ddg_research(prompt: str) -> str:
    """Research function using DuckDuckGo. Returns raw text for MicroQueryRunner to parse."""
    question = _extract_question(prompt)
    if not question:
        return ""

    _rate_limit()

    try:
        import warnings
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            try:
                from ddgs import DDGS
            except ImportError:
                from duckduckgo_search import DDGS
            with DDGS() as ddgs:
                results = list(ddgs.text(question, max_results=5))
    except Exception:
        results = []

    if not results:
        return _fallback_search(question)

    snippets = []
    for r in results[:5]:
        title = r.get("title", "")
        body = r.get("body", "")
        href = r.get("href", "")
        snippets.append(f"{title}: {body} (source: {href})")

    combined = "\n".join(snippets)

    fact = _extract_fact_from_snippets(combined, question)
    return fact


def _extract_question(prompt: str) -> str:
    """Extract the actual question from the micro-query prompt template."""
    lines = prompt.strip().split("\n")
    for line in lines:
        if line.startswith("Question:"):
            return line.replace("Question:", "").strip()
    for line in lines:
        if "?" in line and not line.startswith("Format:") and not line.startswith("Rules:"):
            return line.strip()
    return prompt[:200]


def _extract_fact_from_snippets(text: str, question: str) -> str:
    """Convert search snippets into structured fact JSON for MicroQueryRunner.
    Picks the MOST RELEVANT snippet to the question, not just the first one.
    Applies relevance penalty when snippet doesn't answer the question.
    """
    import re

    snippets = text.split("\n")
    best_snippet, best_relevance = _pick_best_snippet(snippets, question)

    numbers = re.findall(r'[\d,.]+%|[$€£]\s*[\d,.]+[KMBkmb]?|\d{1,3}(?:,\d{3})*(?:\.\d+)?', best_snippet)
    first_url = ""
    url_match = re.search(r'source:\s*(https?://[^\s\)]+)', best_snippet)
    if not url_match:
        url_match = re.search(r'source:\s*(https?://[^\s\)]+)', text)
    if url_match:
        first_url = url_match.group(1)

    value = numbers[0] if numbers else None
    confidence = _score_confidence(best_snippet, first_url, numbers)
    confidence = round(confidence * best_relevance, 2)

    fact_json = {
        "fact": best_snippet[:200],
        "value": value,
        "confidence": confidence,
        "source": first_url or "duckduckgo_search",
        "date": None,
    }

    return json.dumps(fact_json, ensure_ascii=False)


def _pick_best_snippet(snippets: list[str], question: str) -> tuple[str, float]:
    """Score each snippet by keyword overlap with question. Return best + relevance score."""
    q_terms = _extract_keywords(question)
    if not q_terms or not snippets:
        combined = "\n".join(snippets)[:300]
        return combined, 0.5

    best_text = snippets[0] if snippets else ""
    best_score = 0.0

    for snippet in snippets:
        if not snippet.strip():
            continue
        s_lower = snippet.lower()
        hits = sum(1 for t in q_terms if t in s_lower)
        score = hits / len(q_terms)
        if score > best_score:
            best_score = score
            best_text = snippet

    relevance = min(1.0, 0.5 + best_score * 0.5) if best_score > 0 else 0.4
    return best_text[:300], relevance


def _extract_keywords(text: str) -> list[str]:
    """Extract meaningful keywords from a question, ignoring stop words."""
    stop = {
        "what", "how", "is", "the", "a", "an", "in", "of", "for", "to", "and",
        "or", "are", "was", "were", "be", "been", "do", "does", "did", "will",
        "can", "could", "should", "would", "may", "might", "much", "many",
        "average", "typical", "common", "rate", "percentage", "number",
    }
    import re
    words = re.findall(r'[a-zA-Z]{3,}', text.lower())
    return [w for w in words if w not in stop]


_AUTHORITY_DOMAINS = {
    ".gov": 0.15, ".edu": 0.12, "who.int": 0.12, "worldbank.org": 0.12,
    "statista.com": 0.10, "crunchbase.com": 0.08, "pitchbook.com": 0.08,
    "dealstreetasia.com": 0.08, "techcrunch.com": 0.06, "reuters.com": 0.08,
    "bloomberg.com": 0.08, "wikipedia.org": 0.05, "linkedin.com": 0.04,
}


def _score_confidence(text: str, url: str, numbers: list) -> float:
    score = 0.35
    if numbers:
        score += 0.15
    if len(numbers) >= 3:
        score += 0.10
    url_lower = url.lower()
    for domain, boost in _AUTHORITY_DOMAINS.items():
        if domain in url_lower:
            score += boost
            break
    if any(w in text.lower() for w in ["according to", "reported", "data shows", "survey", "study"]):
        score += 0.05
    import re
    if re.search(r'\b20[12]\d\b', text):
        score += 0.05
    return min(0.90, round(score, 2))


def _fallback_search(question: str) -> str:
    """Fallback: use requests to hit DuckDuckGo HTML directly."""
    import requests
    try:
        resp = requests.get(
            "https://html.duckduckgo.com/html/",
            params={"q": question},
            headers={"User-Agent": "Mozilla/5.0"},
            timeout=10,
        )
        if resp.status_code == 200:
            text = resp.text[:2000]
            import re
            snippets = re.findall(r'class="result__snippet">(.*?)</a>', text)
            if snippets:
                combined = " ".join(s[:100] for s in snippets[:3])
                return json.dumps({
                    "fact": combined[:200],
                    "value": None,
                    "confidence": 0.35,
                    "source": "duckduckgo_html_fallback",
                    "date": None,
                }, ensure_ascii=False)
    except Exception:
        pass
    return ""


def create_research_fn(delay_s: float = 1.5) -> callable:
    """Factory: creates a rate-limited research function."""
    global _MIN_DELAY_S
    _MIN_DELAY_S = delay_s
    return ddg_research

#!/usr/bin/env node
/**
 * knowledge-auto-refresh.cjs — SessionStart hook
 * Auto-refreshes stale persona knowledge in background (non-blocking)
 *
 * Triggers when:
 * - >30% of personas are stale (>30 days)
 * - On startup/resume/clear events
 *
 * Behavior:
 * - Queues top 5 most relevant stale personas for refresh
 * - Spawns background refresh (non-blocking)
 * - Updates knowledge-state.yaml after refresh
 *
 * Exit: Always 0 (non-blocking)
 */

try {
  const fs = require('fs');
  const path = require('path');
  const { spawn } = require('child_process');

  let isHookEnabled;
  try {
    ({ isHookEnabled } = require('./lib/ck-config-utils.cjs'));
  } catch {
    isHookEnabled = () => true;
  }

  if (!isHookEnabled('knowledge-auto-refresh')) {
    process.exit(0);
  }

  const STATE_FILE = path.join(__dirname, '..', 'knowledge-state.yaml');
  const REFRESH_LOCK = path.join(__dirname, '.logs', 'kb-refresh.lock');
  const REFRESH_LOG = path.join(__dirname, '.logs', 'kb-refresh.log');
  const PYTHON_PATH = path.join(__dirname, '..', 'skills', '.venv', 'Scripts', 'python.exe');
  const KB_LOADER = path.join(__dirname, '..', 'skills', 'business', 'feedback_loop', 'intelligent-kb-loader.py');

  // Config
  const STALENESS_THRESHOLD_DAYS = 30;
  const STALE_RATIO_TRIGGER = 0.3;  // Trigger refresh if >30% stale
  const MAX_REFRESH_BATCH = 5;

  function ensureLogDir() {
    const logDir = path.join(__dirname, '.logs');
    if (!fs.existsSync(logDir)) fs.mkdirSync(logDir, { recursive: true });
  }

  function isRefreshRunning() {
    if (!fs.existsSync(REFRESH_LOCK)) return false;
    try {
      const lockData = JSON.parse(fs.readFileSync(REFRESH_LOCK, 'utf8'));
      const lockAge = Date.now() - new Date(lockData.started).getTime();
      // Lock expires after 10 minutes
      return lockAge < 600000;
    } catch {
      return false;
    }
  }

  function createRefreshLock(personas) {
    ensureLogDir();
    fs.writeFileSync(REFRESH_LOCK, JSON.stringify({
      started: new Date().toISOString(),
      personas,
      pid: process.pid
    }));
  }

  function clearRefreshLock() {
    if (fs.existsSync(REFRESH_LOCK)) {
      fs.unlinkSync(REFRESH_LOCK);
    }
  }

  function parseKnowledgeState() {
    if (!fs.existsSync(STATE_FILE)) return { personas: {}, threshold: STALENESS_THRESHOLD_DAYS };

    const content = fs.readFileSync(STATE_FILE, 'utf-8');
    const lines = content.split('\n');

    let threshold = STALENESS_THRESHOLD_DAYS;
    let inPersonas = false;
    let currentPersona = null;
    const personas = {};

    for (const line of lines) {
      const trimmed = line.trim();

      if (trimmed.startsWith('staleness_threshold_days:')) {
        threshold = parseInt(trimmed.split(':')[1].trim(), 10) || STALENESS_THRESHOLD_DAYS;
      } else if (trimmed === 'personas:') {
        inPersonas = true;
      } else if (inPersonas && line.startsWith('  ') && !line.startsWith('    ') && trimmed.endsWith(':')) {
        currentPersona = trimmed.slice(0, -1);
        personas[currentPersona] = { last_sync: null, freshness_score: 0 };
      } else if (currentPersona && line.startsWith('    ')) {
        if (trimmed.startsWith('last_sync:')) {
          const val = trimmed.split(':').slice(1).join(':').trim();
          personas[currentPersona].last_sync = val === 'null' ? null : val;
        } else if (trimmed.startsWith('freshness_score:')) {
          personas[currentPersona].freshness_score = parseFloat(trimmed.split(':')[1].trim()) || 0;
        }
      }
    }

    return { personas, threshold };
  }

  function getStalePersonas(personas, threshold) {
    const now = Date.now();
    const msPerDay = 86400000;
    const stale = [];

    for (const [name, data] of Object.entries(personas)) {
      let daysSince = Infinity;

      if (data.last_sync) {
        try {
          const syncDate = new Date(data.last_sync).getTime();
          daysSince = (now - syncDate) / msPerDay;
        } catch {
          daysSince = Infinity;
        }
      }

      if (daysSince > threshold) {
        stale.push({
          name,
          days_stale: Math.floor(daysSince),
          freshness_score: data.freshness_score || 0
        });
      }
    }

    // Sort by staleness (most stale first)
    stale.sort((a, b) => b.days_stale - a.days_stale);

    return stale;
  }

  function spawnBackgroundRefresh(personas) {
    ensureLogDir();

    fs.appendFileSync(REFRESH_LOG,
      `[${new Date().toISOString()}] Queuing ${personas.length} stale personas for refresh\n`
    );

    createRefreshLock(personas);

    // Write priority queue for check-knowledge-staleness.cjs to consume as urgent reminder.
    // Real refresh requires LLM (WebSearch) — hooks can't spawn Claude agents.
    const queuePath = path.join(__dirname, '.logs', 'kb-refresh-queue.json');
    try {
      const queue = {
        queued_at: new Date().toISOString(),
        personas: personas,
        reason: 'auto-detected >30% stale',
        action: 'Run /sync-knowledge to refresh these personas'
      };
      fs.writeFileSync(queuePath, JSON.stringify(queue, null, 2));
      fs.appendFileSync(REFRESH_LOG,
        `[${new Date().toISOString()}] Queue written: ${queuePath}\n`
      );

      // Validate persona loading (--list-all) — actual refresh requires /sync-knowledge
      if (fs.existsSync(PYTHON_PATH) && fs.existsSync(KB_LOADER)) {
        const out = fs.openSync(REFRESH_LOG, 'a');
        const err = fs.openSync(REFRESH_LOG, 'a');
        const child = spawn(PYTHON_PATH, [KB_LOADER, '--list-all', '--json'], {
          detached: true,
          stdio: ['ignore', out, err],
          windowsHide: true,
        });
        child.on('close', () => clearRefreshLock());
        child.unref();
      } else {
        clearRefreshLock();
      }
    } catch (e) {
      fs.appendFileSync(REFRESH_LOG, `[error] ${e.message}\n`);
      clearRefreshLock();
    }
  }

  function main() {
    try {
      // Don't run if refresh already in progress
      if (isRefreshRunning()) {
        process.exit(0);
      }

      const { personas, threshold } = parseKnowledgeState();
      const totalPersonas = Object.keys(personas).length;

      if (totalPersonas === 0) {
        process.exit(0);
      }

      const stalePersonas = getStalePersonas(personas, threshold);
      const staleRatio = stalePersonas.length / totalPersonas;

      // Only auto-refresh if stale ratio exceeds threshold
      if (staleRatio < STALE_RATIO_TRIGGER) {
        process.exit(0);
      }

      // Select top N for refresh
      const toRefresh = stalePersonas.slice(0, MAX_REFRESH_BATCH).map(p => p.name);

      if (toRefresh.length > 0) {
        console.log(`🔄 Auto-refreshing ${toRefresh.length} stale personas in background...`);
        spawnBackgroundRefresh(toRefresh);
      }

      process.exit(0);
    } catch (err) {
      // Silent failure
      if (process.env.CK_DEBUG) {
        console.error(`[knowledge-auto-refresh] Error: ${err.message}`);
      }
      process.exit(0);
    }
  }

  main();
} catch (e) {
  // Minimal crash logging
  try {
    const fs = require('fs');
    const p = require('path');
    const logDir = p.join(__dirname, '.logs');
    if (!fs.existsSync(logDir)) fs.mkdirSync(logDir, { recursive: true });
    fs.appendFileSync(p.join(logDir, 'hook-log.jsonl'),
      JSON.stringify({ ts: new Date().toISOString(), hook: 'knowledge-auto-refresh', status: 'crash', error: e.message }) + '\n');
  } catch (_) {}
  process.exit(0);
}

