1	#!/usr/bin/env node
2	/**
3	 * scout-checker.cjs - Facade for scout-block modules
4	 *
5	 * Provides unified interface to scout-block/* modules for reuse in both
6	 * Claude hooks and OpenCode plugins.
7	 *
8	 * @module scout-checker
9	 */
10	
11	const fs = require('fs');
12	const path = require('path');
13	
14	// Import scout-block modules
15	const { loadPatterns, createMatcher, matchPath } = require('../scout-block/pattern-matcher.cjs');
16	const { extractFromToolInput } = require('../scout-block/path-extractor.cjs');
17	const { detectBroadPatternIssue } = require('../scout-block/broad-pattern-detector.cjs');
18	
19	// ═══════════════════════════════════════════════════════════════════════════
20	// COMMAND PATTERNS
21	// ═══════════════════════════════════════════════════════════════════════════
22	
23	// Build command allowlist - these are allowed even if they contain blocked paths
24	// Handles flags and filters: npm build, pnpm --filter web run build, yarn workspace app build
25	const BUILD_COMMAND_PATTERN = /^(npm|pnpm|yarn|bun)\s+([^\s]+\s+)*(run\s+)?(build|test|lint|dev|start|install|ci|add|remove|update|publish|pack|init|create|exec)/;
26	
27	// Tool commands - JS/TS, Go, Rust, Java, .NET, containers, IaC, Python, Ruby, PHP, Deno, Elixir
28	const TOOL_COMMAND_PATTERN = /^(\.\/)?(npx|pnpx|bunx|tsc|esbuild|vite|webpack|rollup|turbo|nx|jest|vitest|mocha|eslint|prettier|go|cargo|make|mvn|mvnw|gradle|gradlew|dotnet|docker|podman|kubectl|helm|terraform|ansible|bazel|cmake|sbt|flutter|swift|ant|ninja|meson|python3?|pip|uv|deno|bundle|rake|gem|php|composer|ruby|mix|elixir)/;
29	
30	// Allow execution from .venv/bin/ or venv/bin/ (Unix) and .venv/Scripts/ or venv/Scripts/ (Windows)
31	const VENV_EXECUTABLE_PATTERN = /(^|[\/\\])\.?venv[\/\\](bin|Scripts)[\/\\]/;
32	
33	// Allow Python venv creation commands (cross-platform):
34	// - python/python3 -m venv (Unix/macOS/Windows)
35	// - py -m venv (Windows py launcher, supports -3, -3.11, etc.)
36	// - uv venv (fast Rust-based Python package manager)
37	// - virtualenv (legacy but still widely used)
38	const VENV_CREATION_PATTERN = /^(python3?|py)\s+(-[\w.]+\s+)*-m\s+venv\s+|^uv\s+venv(\s|$)|^virtualenv\s+/;
39	
40	// ═══════════════════════════════════════════════════════════════════════════
41	// HELPER FUNCTIONS
42	// ═══════════════════════════════════════════════════════════════════════════
43	
44	/**
45	 * Strip leading ENV variable assignments and command wrappers (sudo, env, etc.)
46	 * e.g., "NODE_ENV=production npm run build" → "npm run build"
47	 * @param {string} command - The command to strip
48	 * @returns {string}
49	 */
50	function stripCommandPrefix(command) {
51	  if (!command || typeof command !== 'string') return command;
52	  let stripped = command.trim();
53	  // Strip env var assignments (KEY=VALUE KEY2=VALUE2 ...)
54	  stripped = stripped.replace(/^(\w+=\S+\s+)+/, '');
55	  // Strip common command wrappers (one level)
56	  stripped = stripped.replace(/^(sudo|env|nice|nohup|time|timeout)\s+/, '');
57	  // Strip env vars again (sudo env VAR=x cmd)
58	  stripped = stripped.replace(/^(\w+=\S+\s+)+/, '');
59	  return stripped.trim();
60	}
61	
62	/**
63	 * Check if a command is a build/tooling command (should be allowed)
64	 * @param {string} command - The command to check
65	 * @returns {boolean}
66	 */
67	function isBuildCommand(command) {
68	  if (!command || typeof command !== 'string') return false;
69	  const trimmed = command.trim();
70	  return BUILD_COMMAND_PATTERN.test(trimmed) || TOOL_COMMAND_PATTERN.test(trimmed);
71	}
72	
73	/**
74	 * Split a compound command into sub-commands on &&, ||, and ;.
75	 * Does NOT split on newlines — newlines in command strings are typically
76	 * heredoc bodies or multiline strings, not compound operators.
77	 * Does not handle operators inside quoted strings (extremely rare in practice).
78	 *
79	 * @param {string} command - The compound command string
80	 * @returns {string[]} Array of sub-commands (trimmed, non-empty)
81	 */
82	function splitCompoundCommand(command) {
83	  if (!command || typeof command !== 'string') return [];
84	  return command.split(/\s*(?:&&|\|\||;)\s*/).filter(cmd => cmd && cmd.trim().length > 0);
85	}
86	
87	/**
88	 * Unwrap shell executor wrappers (bash -c "...", sh -c '...', eval "...").
89	 * Returns the inner command string for re-processing.
90	 * @param {string} command - The command to unwrap
91	 * @returns {string} Inner command, or original if not a shell executor
92	 */
93	function unwrapShellExecutor(command) {
94	  if (!command || typeof command !== 'string') return command;
95	  const match = command.trim().match(
96	    /^(?:(?:bash|sh|zsh)\s+-c|eval)\s+["'](.+)["']\s*$/
97	  );
98	  return match ? match[1] : command;
99	}
100	
101	/**
102	 * Check if command executes from a .venv bin directory
103	 * @param {string} command - The command to check
104	 * @returns {boolean}
105	 */
106	function isVenvExecutable(command) {
107	  if (!command || typeof command !== 'string') return false;
108	  return VENV_EXECUTABLE_PATTERN.test(command);
109	}
110	
111	/**
112	 * Check if command creates a Python virtual environment
113	 * @param {string} command - The command to check
114	 * @returns {boolean}
115	 */
116	function isVenvCreationCommand(command) {
117	  if (!command || typeof command !== 'string') return false;
118	  return VENV_CREATION_PATTERN.test(command.trim());
119	}
120	
121	/**
122	 * Check if command should be allowed (build, venv executable, or venv creation)
123	 * Strips ENV prefixes and command wrappers before checking.
124	 * @param {string} command - The command to check
125	 * @returns {boolean}
126	 */
127	function isAllowedCommand(command) {
128	  const stripped = stripCommandPrefix(command);
129	  return isBuildCommand(stripped) || isVenvExecutable(stripped) || isVenvCreationCommand(stripped);
130	}
131	
132	function findGitRoot(startDir) {
133	  if (!startDir || typeof startDir !== 'string') return null;
134	
135	  let dir = path.resolve(startDir);
136	  const root = path.parse(dir).root;
137	
138	  while (true) {
139	    if (fs.existsSync(path.join(dir, '.git')) || dir === root) {
140	      return fs.existsSync(path.join(dir, '.git')) ? dir : null;
141	    }
142	
143	    dir = path.dirname(dir);
144	  }
145	}
146	
147	/**
148	 * Find an optional project-local .ckignore at the git root config directory.
149	 * This keeps overrides stable regardless of the caller cwd inside the repo.
150	 *
151	 * @param {string} startDir - Directory to start searching from
152	 * @param {string} [configDirName] - Config directory at git root (.claude, .opencode)
153	 * @returns {string|null}
154	 */
155	function findProjectCkignore(startDir, configDirName) {
156	  if (!configDirName || typeof configDirName !== 'string') return null;
157	  const gitRoot = findGitRoot(startDir);
158	  if (!gitRoot) return null;
159	  const candidate = path.join(gitRoot, configDirName, '.ckignore');
160	  return fs.existsSync(candidate) ? candidate : null;
161	}
162	
163	// ═══════════════════════════════════════════════════════════════════════════
164	// MAIN ENTRY POINT
165	// ═══════════════════════════════════════════════════════════════════════════
166	
167	/**
168	 * Check if a tool call accesses blocked directories or uses overly broad patterns
169	 *
170	 * @param {Object} params
171	 * @param {string} params.toolName - Name of tool (Bash, Glob, Read, etc.)
172	 * @param {Object} params.toolInput - Tool input with file_path, path, pattern, command
173	 * @param {Object} [params.options]
174	 * @param {string} [params.options.ckignorePath] - Path to .ckignore file
175	 * @param {string} [params.options.projectCkignorePath] - Explicit project-local .ckignore path
176	 * @param {string} [params.options.claudeDir] - Path to .claude or .opencode directory
177	 * @param {string} [params.options.cwd] - Working directory used to discover a project .ckignore
178	 * @param {string} [params.options.projectConfigDirName] - Git-root config dir for project-local overrides
179	 * @param {boolean} [params.options.checkBroadPatterns] - Check for overly broad glob patterns (default: true)
180	 * @returns {{
181	 *   blocked: boolean,
182	  *   path?: string,
183	  *   pattern?: string,
184	  *   reason?: string,
185	 *   configPath?: string,
186	  *   isBroadPattern?: boolean,
187	  *   suggestions?: string[],
188	  *   isAllowedCommand?: boolean
189	 * }}
190	 */
191	function checkScoutBlock({ toolName, toolInput, options = {} }) {
192	  const {
193	    ckignorePath,
194	    projectCkignorePath,
195	    claudeDir = path.join(process.cwd(), '.claude'),
196	    cwd = process.cwd(),
197	    projectConfigDirName,
198	    checkBroadPatterns = true
199	  } = options;
200	
201	  // Unwrap shell executor wrappers (bash -c "...", eval "...")
202	  // so the inner command gets properly analyzed
203	  if (toolInput.command) {
204	    const unwrapped = unwrapShellExecutor(toolInput.command);
205	    if (unwrapped !== toolInput.command) {
206	      toolInput = { ...toolInput, command: unwrapped };
207	    }
208	  }
209	
210	  // For Bash commands, split compound commands (&&, ||, ;) and check
211	  // each sub-command independently. This prevents "echo msg && npm run build"
212	  // from being blocked due to "build" token in the allowed build sub-command.
213	  // Must split BEFORE isAllowedCommand because BUILD_COMMAND_PATTERN has no end
214	  // anchor and would match the prefix of "npm run build && cat dist/file.js".
215	  if (toolInput.command) {
216	    const subCommands = splitCompoundCommand(toolInput.command);
217	    const nonAllowed = subCommands.filter(cmd => !isAllowedCommand(cmd.trim()));
218	    if (nonAllowed.length === 0) {
219	      return { blocked: false, isAllowedCommand: true };
220	    }
221	    // Only extract paths from non-allowed sub-commands
222	    if (nonAllowed.length < subCommands.length) {
223	      toolInput = { ...toolInput, command: nonAllowed.join(' ; ') };
224	    }
225	  }
226	
227	  // Check for overly broad glob patterns (Glob tool)
228	  if (checkBroadPatterns && (toolName === 'Glob' || toolInput.pattern)) {
229	    const broadResult = detectBroadPatternIssue(toolInput);
230	    if (broadResult.blocked) {
231	      return {
232	        blocked: true,
233	        isBroadPattern: true,
234	        pattern: toolInput.pattern,
235	        reason: broadResult.reason || 'Pattern too broad - may fill context with too many files',
236	        suggestions: broadResult.suggestions || []
237	      };
238	    }
239	  }
240	
241	  // Resolve .ckignore path
242	  const resolvedCkignorePath = ckignorePath || path.join(claudeDir, '.ckignore');
243	  const discoveredProjectCkignorePath = projectCkignorePath || findProjectCkignore(cwd, projectConfigDirName);
244	  const resolvedProjectCkignorePath = discoveredProjectCkignorePath
245	    && path.resolve(discoveredProjectCkignorePath) !== path.resolve(resolvedCkignorePath)
246	      ? discoveredProjectCkignorePath
247	      : null;
248	  const configPath = resolvedProjectCkignorePath || resolvedCkignorePath;
249	
250	  // Load patterns and create matcher
251	  const patterns = loadPatterns(resolvedCkignorePath, resolvedProjectCkignorePath);
