1	#!/usr/bin/env node
2	/**
3	 * path-extractor.cjs - Extract paths from Claude Code tool inputs
4	 *
5	 * Extracts file_path, path, pattern params and parses Bash commands
6	 * to find all path-like arguments.
7	 */
8	
9	// Flags that indicate the following value should NOT be checked as a path
10	// These are "exclude" semantics - the user is explicitly skipping these paths
11	const EXCLUDE_FLAGS = [
12	  '--exclude', '--ignore', '--skip', '--prune',
13	  '-x',           // tar exclude shorthand
14	  '-path',        // find -path (used with -prune)
15	  '--exclude-dir' // grep --exclude-dir
16	];
17	
18	// Filesystem commands where bare directory names (build, dist, etc.)
19	// should be extracted as paths. For non-fs commands (grep, echo, sed),
20	// only tokens that look like actual paths (contain / or extension) are extracted.
21	const FILESYSTEM_COMMANDS = [
22	  'cd', 'ls', 'cat', 'head', 'tail', 'less', 'more',
23	  'rm', 'cp', 'mv', 'find', 'touch', 'mkdir', 'rmdir',
24	  'stat', 'file', 'du', 'tree', 'chmod', 'chown', 'ln',
25	  'readlink', 'realpath', 'wc', 'tee', 'tar', 'zip', 'unzip',
26	  'open', 'code', 'vim', 'nano', 'bat', 'rsync', 'scp', 'diff'
27	];
28	
29	/**
30	 * Extract all paths from a tool_input object
31	 * Handles: file_path, path, pattern params and command strings
32	 *
33	 * @param {Object} toolInput - The tool_input from hook JSON
34	 * @returns {string[]} Array of extracted paths
35	 */
36	function extractFromToolInput(toolInput) {
37	  const paths = [];
38	
39	  if (!toolInput || typeof toolInput !== 'object') {
40	    return paths;
41	  }
42	
43	  // Direct path params (Read, Edit, Write, Grep, Glob tools)
44	  const directParams = ['file_path', 'path', 'pattern'];
45	  for (const param of directParams) {
46	    if (toolInput[param] && typeof toolInput[param] === 'string') {
47	      const normalized = normalizeExtractedPath(toolInput[param]);
48	      if (normalized) paths.push(normalized);
49	    }
50	  }
51	
52	  // Extract from Bash command if present
53	  if (toolInput.command && typeof toolInput.command === 'string') {
54	    const cmdPaths = extractFromCommand(toolInput.command);
55	    paths.push(...cmdPaths);
56	  }
57	
58	  return paths.filter(Boolean);
59	}
60	
61	/**
62	 * Extract path-like segments from a Bash command string.
63	 *
64	 * Uses pipe-segment-aware command context: for filesystem commands (cd, cat, ls, rm, etc.)
65	 * bare blocked directory names are extracted with priority. For non-filesystem commands
66	 * (grep, echo, sed, etc.) only tokens that structurally look like paths are extracted,
67	 * preventing false positives on search terms and string arguments.
68	 *
69	 * @param {string} command - The command string
70	 * @returns {string[]} Array of extracted paths
71	 */
72	function extractFromCommand(command) {
73	  if (!command || typeof command !== 'string') {
74	    return [];
75	  }
76	
77	  const paths = [];
78	
79	  // First, extract quoted strings (preserve spaces in paths)
80	  const quotedPattern = /["']([^"']+)["']/g;
81	  let match;
82	  while ((match = quotedPattern.exec(command)) !== null) {
83	    const content = match[1];
84	
85	    // Skip sed/awk regex expressions (s/pattern/replacement/flags)
86	    if (/^s[\/|@#,]/.test(content)) continue;
87	
88	    if (looksLikePath(content)) {
89	      paths.push(normalizeExtractedPath(content));
90	    }
91	  }
92	
93	  // Remove quoted strings for unquoted path extraction
94	  const withoutQuotes = command.replace(/["'][^"']*["']/g, ' ');
95	
96	  // Split on whitespace and extract path-like tokens
97	  const tokens = withoutQuotes.split(/\s+/).filter(Boolean);
98	
99	  // Track command context per pipe segment
100	  let commandName = null;
101	  let isFsCommand = false;
102	  let skipNextToken = false;
103	  let heredocDelimiter = null;
104	  let nextIsHeredocDelimiter = false;
105	
106	  for (const token of tokens) {
107	    // Heredoc delimiter capture (after << or <<-)
108	    if (nextIsHeredocDelimiter) {
109	      heredocDelimiter = token.replace(/^['"]/, '').replace(/['"]$/, '');
110	      nextIsHeredocDelimiter = false;
111	      continue;
112	    }
113	
114	    // Skip heredoc body content until closing delimiter
115	    if (heredocDelimiter) {
116	      if (token === heredocDelimiter) {
117	        heredocDelimiter = null;
118	      }
119	      continue;
120	    }
121	
122	    // Detect heredoc start: <<EOF, <<'EOF', <<"EOF", <<-EOF
123	    if (token.startsWith('<<') && token.length > 2) {
124	      heredocDelimiter = token.replace(/^<<-?['"]?/, '').replace(/['"]?$/, '');
125	      continue;
126	    }
127	    if (token === '<<' || token === '<<-') {
128	      nextIsHeredocDelimiter = true;
129	      continue;
130	    }
131	
132	    // Skip value after exclude flags (--exclude node_modules format)
133	    if (skipNextToken) {
134	      skipNextToken = false;
135	      continue;
136	    }
137	
138	    // Reset command context at command/pipe boundaries
139	    if (token === '&&' || token === ';' || token.startsWith('|')) {
140	      commandName = null;
141	      isFsCommand = false;
142	      continue;
143	    }
144	
145	    // Skip flags and shell operators
146	    if (isSkippableToken(token)) {
147	      if (EXCLUDE_FLAGS.includes(token)) {
148	        skipNextToken = true;
149	      }
150	      continue;
151	    }
152	
153	    // Determine the command for this pipe segment (first non-flag token)
154	    if (commandName === null) {
155	      commandName = token.toLowerCase();
156	      isFsCommand = FILESYSTEM_COMMANDS.includes(commandName);
157	      // Skip the command word itself
158	      if (isCommandKeyword(token) || isFsCommand) continue;
159	      // Non-keyword command (e.g., ./script.sh) — fall through to path check
160	    }
161	
162	    // For filesystem commands, extract blocked dir names with priority.
163	    // "cd build", "ls dist", "cat node_modules/..." — "build"/"dist" are paths here.
164	    if (isFsCommand && isBlockedDirName(token)) {
165	      paths.push(normalizeExtractedPath(token));
166	      continue;
167	    }
168	
169	    // Skip common non-path command words
170	    if (isCommandKeyword(token)) continue;
171	
172	    // Check if it looks like a path
173	    if (looksLikePath(token)) {
174	      paths.push(normalizeExtractedPath(token));
175	    }
176	  }
177	
178	  return paths;
179	}
180	
181	// Common blocked directory names that should be extracted even if they
182	// match command keywords (e.g., "build" is both a subcommand and a dir name)
183	// Keep in sync with DEFAULT_PATTERNS in pattern-matcher.cjs
184	const BLOCKED_DIR_NAMES = [
185	  'node_modules', '__pycache__', '.git', 'dist', 'build',
186	  '.next', '.nuxt', '.venv', 'venv', 'vendor', 'target', 'coverage'
187	];
188	
189	/**
190	 * Check if token is exactly a blocked directory name
191	 * This takes priority over command keyword filtering
192	 *
193	 * @param {string} token - Token to check
194	 * @returns {boolean}
195	 */
196	function isBlockedDirName(token) {
197	  return BLOCKED_DIR_NAMES.includes(token);
198	}
199	
200	/**
201	 * Check if a string looks like a file path
202	 *
203	 * @param {string} str - String to check
204	 * @returns {boolean}
205	 */
206	function looksLikePath(str) {
207	  if (!str || str.length < 2) return false;
208	
209	  // Contains path separator
210	  if (str.includes('/') || str.includes('\\')) return true;
211	
212	  // Starts with relative path indicator
213	  if (str.startsWith('./') || str.startsWith('../')) return true;
214	
215	  // Has file extension (likely a file)
216	  if (/\.\w{1,6}$/.test(str)) return true;
217	
218	  // Looks like a directory path
219	  if (/^[a-zA-Z0-9_-]+\//.test(str)) return true;
220	
221	  return false;
222	}
223	
224	/**
225	 * Check if token should be skipped (flags, operators)
226	 *
227	 * @param {string} token - Token to check
228	 * @returns {boolean}
229	 */
230	function isSkippableToken(token) {
231	  // Flags
232	  if (token.startsWith('-')) return true;
233	
234	  // Shell operators
235	  if (['|', '||', '&&', '>', '>>', '<', '<<', '&', ';'].includes(token)) return true;
236	  if (token.startsWith('|') || token.startsWith('>') || token.startsWith('<')) return true;
237	  if (token.startsWith('&')) return true;
238	
239	  // Numeric values
240	  if (/^\d+$/.test(token)) return true;
241	
242	  return false;
243	}
244	
245	/**
246	 * Check if token is a common command keyword (not a path)
247	 *
248	 * @param {string} token - Token to check
249	 * @returns {boolean}
250	 */
251	function isCommandKeyword(token) {
252	  const keywords = [
253	    // Shell commands
254	    'echo', 'cat', 'ls', 'cd', 'rm', 'cp', 'mv', 'find', 'grep', 'head', 'tail',
255	    'wc', 'du', 'tree', 'touch', 'mkdir', 'rmdir', 'pwd', 'which', 'env', 'export',
256	    'source', 'bash', 'sh', 'zsh', 'true', 'false', 'test', 'xargs', 'tee', 'sort',
257	    'uniq', 'cut', 'tr', 'sed', 'awk', 'diff', 'chmod', 'chown', 'ln', 'file',
258	
259	    // Package managers and their subcommands
260	    'npm', 'pnpm', 'yarn', 'bun', 'npx', 'pnpx', 'bunx', 'node',
261	    'run', 'build', 'test', 'lint', 'dev', 'start', 'install', 'ci', 'exec',
262	    'add', 'remove', 'update', 'publish', 'pack', 'init', 'create',
263	
264	    // Build tools
265	    'tsc', 'esbuild', 'vite', 'webpack', 'rollup', 'turbo', 'nx',
266	    'jest', 'vitest', 'mocha', 'eslint', 'prettier',
267	
268	    // Git
269	    'git', 'commit', 'push', 'pull', 'merge', 'rebase', 'checkout', 'branch',
270	    'status', 'log', 'diff', 'add', 'reset', 'stash', 'fetch', 'clone',
271	
272	    // Docker
273	    'docker', 'compose', 'up', 'down', 'ps', 'logs', 'exec', 'container', 'image',
274	
275	    // Misc
276	    'sudo', 'time', 'timeout', 'watch', 'make', 'cargo', 'python', 'python3', 'pip',
277	    'ruby', 'gem', 'go', 'rust', 'java', 'javac', 'mvn', 'gradle'
